macro_rules! lucide {
    ($($id:ident, $name:literal, $body:literal;)*) => {
        $(
            pub static $id: Icon = Icon {
                name: concat!("lucide-", $name),
                view: 24.0,
                body: concat!(
                    r#"<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">"#,
                    $body,
                    "</g>"
                ),
            };
        )*
    };
}

